#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# Board API owner setup (spec §3). Run from the repo root: bash scripts/worker-setup.sh
# Secrets go straight from hidden input into GitHub Environment secrets; nothing secret touches disk or the screen.
TOTAL_STAGES=10
cd "$(dirname "$0")/.."   # every path below is relative to the repo root
ENV_FILE=".scratch/worker-setup.env"   # public values only (account ids, D1 ids, URLs), for re-runs
mkdir -p .scratch

REPO=$(gh repo view --json nameWithOwner -q .nameWithOwner 2>/dev/null || echo "Seif-Sallam/Wobbly-Mart")

# env_secret ENV NAME VALUE: a GitHub Environment secret, value piped (never an argument, never printed).
env_secret() {
  if [[ -z "$3" ]]; then note "kept the existing $1/$2"; return; fi
  if printf '%s' "$3" | gh secret set "$2" --env "$1" --repo "$REPO" >/dev/null 2>&1; then
    WRITTEN_SECRET+=("$1/$2"); printf '  %s✓ set%s %s secret %s\n' "$GREEN" "$RESET" "$1" "$2"
  else
    SKIPPED+=("$1 secret $2 (gh secret set $2 --env $1)"); warn "couldn't set $1/$2; set it by hand"
  fi
}

# make_env ENV BRANCH: a GitHub Environment that only BRANCH can deploy from.
make_env() {
  if gh api -X PUT "repos/$REPO/environments/$1" --input - >/dev/null 2>&1 <<JSON
{"deployment_branch_policy": {"protected_branches": false, "custom_branch_policies": true}}
JSON
  then
    gh api -X POST "repos/$REPO/environments/$1/deployment-branch-policies" -f name="$2" -f type=branch >/dev/null 2>&1 || true
    printf '  %s✓ environment%s %s (deploys from %s only)\n' "$GREEN" "$RESET" "$1" "$2"
  else
    SKIPPED+=("GitHub Environment $1 limited to branch $2"); warn "couldn't create environment $1"
  fi
}

# set_d1_id ENV DB ID: replaces the placeholder id in worker/wrangler.toml (D1 ids are not secret).
set_d1_id() {
  sed -i.bak "s/\"$1-$2-id\"/\"$3\"/" worker/wrangler.toml
  rm -f worker/wrangler.toml.bak
  printf '  %s✓ wrote%s %s %s id → worker/wrangler.toml\n' "$GREEN" "$RESET" "$1" "$2"
}

# cloudflare ENV: one Cloudflare account's Worker, D1 databases, token and GitHub Environment.
cloudflare() {
  local env="$1" upper branch acct
  upper=$(printf '%s' "$env" | tr '[:lower:]' '[:upper:]')
  branch=$([[ "$env" == staging ]] && echo release-03-leaderboard || echo main)

  stage "$env: the Cloudflare account"
  if [[ "$env" == staging ]]; then
    say "Staging lives on a SECOND, separate free Cloudflare account, so its traffic can't spend production's quota."
    step "Sign up with another email (or log in to it). Use a private window to stay logged in to production."
  else
    say "Production uses your main Cloudflare account."
  fi
  open_url "https://dash.cloudflare.com/"
  step "Open Workers & Pages once so the account gets a workers.dev subdomain (Settings shows it)."
  step "Account home → the ⋯ next to the account name → Copy account ID."
  ask "${upper}_ACCOUNT_ID" "Paste the $env account ID:"
  acct="${upper}_ACCOUNT_ID"; write_env "$acct" "${!acct}"
  ask "${upper}_SUBDOMAIN" "Its workers.dev subdomain (the part before .workers.dev):"
  acct="${upper}_SUBDOMAIN"; write_env "$acct" "${!acct}"

  stage "$env: three D1 databases"
  open_url "https://dash.cloudflare.com/?to=/:account/workers/d1"
  say "Create three databases (Storage & Databases → D1 → Create), names exactly:"
  step "wobbly_board   wobbly_replay   wobbly_save"
  say "Each database page shows its ID (a UUID) at the top."
  for db in board replay save; do
    ask "${upper}_D1_${db^^}" "Paste the wobbly_$db ID:"
    acct="${upper}_D1_${db^^}"; write_env "$acct" "${!acct}"; set_d1_id "$env" "$db" "${!acct}"
  done
  note "Rate limiters need nothing: namespace ids 1001-1004 in wrangler.toml are per account."

  stage "$env: the CI deploy token"
  open_url "https://dash.cloudflare.com/profile/api-tokens"
  step "Create Token → Create Custom Token, name it 'wobbly-mart-ci-$env'."
  step "Permissions: Account · Workers Scripts · Edit, and Account · D1 · Read. Nothing else (CI never migrates)."
  step "Account Resources: Include → this $env account only. Create, then copy the token."
  ask_secret TOKEN "Paste the token (hidden):"
  make_env "worker-$env" "$branch"
  env_secret "worker-$env" CLOUDFLARE_API_TOKEN "$TOKEN"
  acct="${upper}_ACCOUNT_ID"; env_secret "worker-$env" CLOUDFLARE_ACCOUNT_ID "${!acct}"
  TOKEN=""

  stage "$env: the game's API URL"
  acct="${upper}_SUBDOMAIN"
  local name; name=$([[ "$env" == staging ]] && echo wobbly-mart-api-staging || echo wobbly-mart-api)
  local url="https://$name.${!acct}.workers.dev"
  say "The Worker will answer at $url"
  set_var "VITE_API_URL_${upper}" "$url"
}

banner "Wobbly Mart · Board API setup"

cloudflare staging

stage "staging: apply the D1 migrations"
say "This logs Wrangler in to the STAGING account in your browser, then creates the tables."
warn "Pick the staging account when the browser asks. Production is migrated only at the release gate."
if confirm "Apply worker/migrations to the staging databases now?"; then
  npx wrangler login
  for db in board replay save; do
    CLOUDFLARE_ACCOUNT_ID="$STAGING_ACCOUNT_ID" npx wrangler d1 migrations apply "wobbly_$db" --remote --env staging --config worker/wrangler.toml
  done
  npx wrangler logout
else
  SKIPPED+=("staging migrations: npx wrangler d1 migrations apply wobbly_<db> --remote --env staging --config worker/wrangler.toml")
fi

cloudflare production

stage "GitHub: Dependabot alerts"
if confirm "Turn on Dependabot alerts for $REPO?"; then
  gh api -X PUT "repos/$REPO/vulnerability-alerts" >/dev/null 2>&1 && printf '  %s✓ on%s\n' "$GREEN" "$RESET" \
    || SKIPPED+=("Dependabot alerts: Settings → Code security → Dependabot alerts")
fi
say "Commit worker/wrangler.toml (it now holds the six D1 ids) in a PR into release-03-leaderboard."
pause

finish
}

run_wizard "$@"; exit
